from django.db import migrations, models


def preserve_legacy_voice_answers(apps, schema_editor):
    InterviewQuestion = apps.get_model("interview", "InterviewQuestion")
    questions = list(InterviewQuestion.objects.filter(answer_mode="voice"))
    for question in questions:
        recorded = bool((question.answer_text or "").strip() or question.audio_file)
        if recorded:
            # The former browser transcript remains useful for content review,
            # but it cannot be relabelled as authoritative raw ASR evidence.
            question.provisional_transcript = question.answer_text
            question.corrected_transcript = question.answer_text
            question.transcription_status = "unavailable"
            question.voice_analysis_status = "unavailable"
        else:
            question.transcription_status = "pending"
            question.voice_analysis_status = "pending"
    if questions:
        InterviewQuestion.objects.bulk_update(
            questions,
            [
                "provisional_transcript",
                "corrected_transcript",
                "transcription_status",
                "voice_analysis_status",
            ],
        )


